script:
(function () {
  'use strict';
  // Switching an existing mortgage to biweekly payments, starting from today's balance.
  //   Monthly (as now): interest = balance x rate / 12 each month (to the cent), then the P&I payment M,
  //   until the balance is gone.
  //   True biweekly: M / 2 (+ any extra) every two weeks, 26 a year, interest = balance x rate / 26
  //   per period (to the cent). Months taken = periods x 12 / 26, rounded up.
  //   Held and sent monthly: the lender gets M (+ 26/12 of the extras) each month and one extra M
  //   every 12th month (the 26th half-payment of the year), with monthly interest.
  //   Fees = setup fee + fee per draft x number of biweekly drafts until payoff.
  //   Each draft = M / 2 + escrow / 2 + extra. "Do it yourself" = M x 13 / 12 paid monthly.
  // Verified in Node (scratchpad b6mtg/be.test.js): $250,000 at 6.5% paying $1,750: payoff in 276
  //   months, matching the closed form n = -ln(1 - Bi/M) / ln(1 + i) = 275.15 rounded up, interest
  //   $231,514.45 vs n x M - B = $231,513.78 (cent rounding); true biweekly $875: 502 periods vs the
  //   closed form 501.73 with j = 0.065/26, interest $189,015.14 vs $189,014.89; the held plan pays
  //   exactly 13 payments a year; fees = setup + fee x drafts ($295 + $2.50 x 507 = $1,562.50);
  //   0% rate -> 250 months monthly and 500 periods (231 months) biweekly for $250,000 / $1,000, $0
  //   interest; a payment below the monthly interest shows an error; no NaN/Infinity on bad input.
  var MAX_MONTHS = 1200;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var monthName = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }
  function cents(x) { return Math.round(x * 100) / 100; }

  function read(id, blankAs) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAs === undefined ? NaN : blankAs;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  // Monthly payments of `pay`, plus `bonus` added every 12th month. Returns months, interest and
  // the balance / interest for each year.
  function monthly(balance, rate, pay, bonus) {
    var i = rate / 12, bal = balance, interest = 0, yearInt = 0, years = [];
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var it = cents(bal * i);
      bal += it;
      var p = Math.min(bal, pay + (m % 12 === 0 ? bonus : 0));
      bal -= p; interest += it; yearInt += it;
      if (bal < 0.005) bal = 0;
      if (m % 12 === 0 || bal === 0) { years.push({ balance: bal, interest: yearInt }); yearInt = 0; }
      if (bal === 0) return { months: m, interest: interest, years: years, ok: true };
    }
    return { months: MAX_MONTHS, interest: interest, years: years, ok: false };
  }

  // True biweekly: `pay` every two weeks, 26 periods a year.
  function biweekly(balance, rate, pay) {
    var j = rate / 26, bal = balance, interest = 0, yearInt = 0, years = [];
    for (var k = 1; k <= MAX_MONTHS * 26 / 12; k++) {
      var it = cents(bal * j);
      bal += it;
      bal -= Math.min(bal, pay);
      interest += it; yearInt += it;
      if (bal < 0.005) bal = 0;
      if (k % 26 === 0 || bal === 0) { years.push({ balance: bal, interest: yearInt }); yearInt = 0; }
      if (bal === 0) return { periods: k, months: Math.ceil(k * 12 / 26 - 1e-9), interest: interest, years: years, ok: true };
    }
    return { periods: k, months: MAX_MONTHS, interest: interest, years: years, ok: false };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function payoffDate(months) {
    var d = new Date();
    var total = d.getFullYear() * 12 + d.getMonth() + months - 1;
    return monthName[total % 12] + ' ' + Math.floor(total / 12);
  }

  function clearResults() {
    ['beDraft', 'beSooner', 'beSaved', 'beNet'].forEach(function (id) { setText(id, '–'); setText(id + 'Note', ''); });
    ['beOldEnd', 'beNewEnd', 'beOldInt', 'beNewInt', 'beFees', 'beDiy'].forEach(function (id) { setText(id, '–'); });
    el('beNote').hidden = true;
    el('beYears').innerHTML = '';
  }

  function update() {
    var balance = read('beBalance'), rate = read('beRate'), pay = read('bePay'), escrow = read('beEscrow', 0),
        setup = read('beSetup', 0), fee = read('beFee', 0), extra = read('beExtra', 0), held = el('beMethod').value === 'held';
    var msg = '';
    if (isNaN(balance) || balance <= 0 || balance > 1e9) msg = 'Enter a current loan balance greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 30) msg = 'Enter an interest rate from 0% to 30%.';
    else if (isNaN(pay) || pay <= 0 || pay > 1e8) msg = 'Enter your monthly principal and interest payment.';
    else if (pay <= cents(balance * rate / 1200)) msg = 'That payment does not cover the monthly interest of ' + money.format(balance * rate / 1200) + '. Check the balance, rate and payment.';
    else if ([escrow, setup, fee, extra].some(function (v) { return isNaN(v) || v < 0 || v > 1e7; })) msg = 'Enter escrow, fees and extra payments of $0 or more.';
    var error = el('beError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var r = rate / 100;
    var base = monthly(balance, r, pay, 0);
    if (!base.ok) { error.hidden = false; error.textContent = 'At this payment the loan would take more than 100 years to repay. Check the figures.'; clearResults(); return; }
    var plan = held ? monthly(balance, r, pay + extra * 26 / 12, pay) : biweekly(balance, r, pay / 2 + extra);
    var drafts = held ? Math.ceil(plan.months * 26 / 12 - 1e-9) : plan.periods;
    var fees = setup + fee * drafts;
    var diy = monthly(balance, r, pay * 13 / 12, 0);

    var draft = pay / 2 + escrow / 2 + extra;
    setText('beDraft', money.format(draft));
    setText('beDraftNote', 'Every two weeks, 26 a year: ' + money.format(draft * 26) + ' a year vs ' + money.format((pay + escrow) * 12) + ' paying monthly' + (escrow > 0 ? ' (both including escrow).' : '.'));
    var sooner = base.months - plan.months;
    setText('beSooner', duration(Math.max(0, sooner)));
    setText('beSoonerNote', 'Debt-free around ' + payoffDate(plan.months) + ' instead of ' + payoffDate(base.months) + '.');
    var saved = base.interest - plan.interest;
    setText('beSaved', money.format(saved));
    setText('beSavedNote', held ? 'The service holds half-payments until the monthly due date, so they earn you nothing in between.' : 'Each half-payment reduces the balance as soon as it arrives.');
    var net = saved - fees;
    setText('beNetLabel', net >= 0 ? 'Savings after fees' : 'Fees exceed the savings by');
    setText('beNet', money.format(Math.abs(net)));
    setText('beNetNote', fees > 0 ? money.format(fees) + ' in fees over ' + drafts + ' drafts.' : 'No fees entered.');

    setText('beOldEnd', duration(base.months) + ' (' + payoffDate(base.months) + ')');
    setText('beNewEnd', duration(plan.months) + ' (' + payoffDate(plan.months) + ')');
    setText('beOldInt', money.format(base.interest));
    setText('beNewInt', money.format(plan.interest));
    setText('beFees', money.format(fees));
    setText('beDiy', money.format(base.interest - diy.interest) + ', paid off in ' + duration(diy.months));

    var note = el('beNote');
    note.hidden = !(fees > 0 || held);
    if (!note.hidden) setText('beNoteText', 'Adding ' + money.format(pay / 12) + ' to each monthly payment yourself repays the same extra payment a year with no fees and saves ' + money.format(base.interest - diy.interest) + ' in interest. Check that your servicer applies extra amounts to principal.');

    var html = [], n = Math.max(base.years.length, plan.years.length);
    for (var y = 0; y < n; y++) {
      var a = base.years[y] || { balance: 0, interest: 0 }, b = plan.years[y] || { balance: 0, interest: 0 };
      html.push('<tr><td>' + (y + 1) + '</td><td>' + money.format(a.interest) + '</td><td>' + money.format(a.balance) + '</td><td>' +
        money.format(b.interest) + '</td><td>' + money.format(b.balance) + '</td><td>' + money.format(a.balance - b.balance) + '</td></tr>');
    }
    el('beYears').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('beForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
